"""Loads the portfolio knowledge base (arc/knowledge/**/*.md, generated by `npm run arc:knowledge`) into chunks."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from pathlib import Path

HEADER = re.compile(r"<!-- arc: (\{.*?\}) -->\n")
SENTENCE = re.compile(r"(?<=[.!?])\s+(?=[A-Z*\"(])")


@dataclass(frozen=True)
class Chunk:
    id: str  # "<doc id>#<n>"
    doc_id: str
    title: str
    category: str
    text: str
    keys: tuple[str, ...] = ()
    links: tuple[dict, ...] = field(default=())
    entity: str | None = None


def split_text(text: str, max_chars: int = 900) -> list[str]:
    """Splits long documents at sentence boundaries, repeating one sentence of overlap between chunks."""
    if len(text) <= max_chars:
        return [text]
    chunks, current = [], []
    for sentence in SENTENCE.split(text):
        if current and len(" ".join(current + [sentence])) > max_chars:
            chunks.append(" ".join(current))
            current = current[-1:]
        current.append(sentence)
    chunks.append(" ".join(current))
    return chunks


def load_knowledge(directory: Path) -> list[Chunk]:
    if not directory.is_dir():
        raise FileNotFoundError(f"no knowledge base at {directory}: run `npm run arc:knowledge` in the portfolio")
    chunks: list[Chunk] = []
    for path in sorted(directory.rglob("*.md")):
        raw = path.read_text(encoding="utf-8")
        m = HEADER.match(raw)
        meta = json.loads(m.group(1)) if m else {}
        body = raw[m.end():] if m else raw
        body = re.sub(r"^# .*\n+", "", body).strip()  # the title is in the metadata
        doc_id = meta.get("id", path.stem)
        for i, piece in enumerate(split_text(body)):
            chunks.append(Chunk(
                id=f"{doc_id}#{i}",
                doc_id=doc_id,
                title=meta.get("title", path.stem),
                category=path.parent.relative_to(directory).as_posix(),
                text=piece,
                keys=tuple(meta.get("keys", [])),
                links=tuple(meta.get("links", [])),
                entity=meta.get("entity"),
            ))
    if not chunks:
        raise FileNotFoundError(f"the knowledge base at {directory} is empty")
    return chunks


def load_links(directory: Path) -> dict:
    """The resume, GitHub, LinkedIn, email, phone and project repo links Arc may open for a visitor."""
    path = directory / "links.json"
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}


def load_project_aliases(directory: Path) -> dict[str, list[str]]:
    """{"roadguard": ["roadguard", "accident detection", …], …}: the names people use for each project."""
    path = directory / "projects.json"
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
